package application_test
import ("context"; "encoding/json"; "os"; "path/filepath"; "testing"; "time"; "evidence/internal/application"; "evidence/internal/domain"; "evidence/internal/repository")
func TestBug02FrozenScopeIdentityAndCredential(t *testing.T){a:=domain.ConditionVersion{Scope:domain.ResourceScope{Type:"doc",Identifier:"a"}}; b:=a; b.Scope.Identifier="b"; if a.ComputeHash()==b.ComputeHash(){t.Fatal("different resources share hash")}; ctx:=context.Background(); root:=t.TempDir(); repo,_:=repository.NewFileRepository(root); exp:=time.Now().Add(time.Hour); frozen:=domain.ResourceScope{Type:"doc",Identifier:"frozen"}; current:=domain.ResourceScope{Type:"doc",Identifier:"current"}; cv:=domain.ConditionVersion{ID:"cv",RequestID:"r",Scope:frozen}; _=repo.SaveConditionVersion(ctx,cv); _=repo.SaveRequest(ctx,domain.AuthorizationRequest{ID:"r",Status:domain.StatusUnderReview,CurrentVersionID:"cv",ResourceScope:current,ExpiresAt:&exp,Version:1}); if err:=application.NewAuthorizationService(repo).Enable(ctx,"r","u");err!=nil{t.Fatal(err)}; files,_:=os.ReadDir(filepath.Join(root,"decisions")); raw,_:=os.ReadFile(filepath.Join(root,"decisions",files[0].Name())); var d domain.DecisionCredential; _=json.Unmarshal(raw,&d); if d.ScopeSnapshot.Identifier!="frozen"{t.Fatalf("scope: %#v",d.ScopeSnapshot)}}
